#!/usr/bin/env bash
# Generate AxiomConfig.swift with the ingest token baked in.
# The generated file is gitignored. Run before building.
#
#   ./tools/axiom-config.sh
#
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SECRETS="${AXIOM_SECRETS:-$HOME/.mesh-rig/secrets/axiom.env}"
DATASET="p2pmesh-dev"

# Read token
if [ -n "${AXIOM_INGEST_TOKEN:-}" ]; then
  TOKEN="$AXIOM_INGEST_TOKEN"
elif [ -r "$SECRETS" ]; then
  TOKEN="$(sed -n 's/^AXIOM_INGEST_TOKEN=//p' "$SECRETS" | head -1)"
else
  echo "✗ No AXIOM_INGEST_TOKEN in env or $SECRETS" >&2
  exit 2
fi

[ -n "$TOKEN" ] || { echo "✗ AXIOM_INGEST_TOKEN is empty" >&2; exit 2; }

cat > "$ROOT/Shared/AxiomConfig.swift" <<SWIFT
// AUTO-GENERATED by tools/axiom-config.sh — DO NOT EDIT OR COMMIT
enum AxiomConfig {
    static let dataset = "$DATASET"
    static let token = "$TOKEN"
}
SWIFT

echo "✓ Shared/AxiomConfig.swift written (dataset: $DATASET)"
